BEGIN;
-- 191 müşteri
-- 268 ziyaret
UPDATE saha_musteri m SET kayit_kaynagi='EXCEL_IMPORT_KONTROL', updated_at=now() WHERE m.tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND m.sorumlu_rep='bd1787e9-2eb8-415b-9423-af3766f0fab4' AND m.aktif=true AND m.musteri_kodu IS NULL AND m.kayit_kaynagi='SAHA_ZIYARETI' AND EXISTS (SELECT 1 FROM saha_ziyaret z WHERE z.musteri_id=m.id AND z.rep_id=m.sorumlu_rep);
COMMIT;
\pset pager off
\echo '== ADNAN sonrası =='
SELECT count(*) FILTER (WHERE kayit_kaynagi='EXCEL_IMPORT_KONTROL') AS inceleme, count(*) FILTER (WHERE musteri_kodu IS NOT NULL) AS erp_linkli, count(*) AS toplam FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND sorumlu_rep='bd1787e9-2eb8-415b-9423-af3766f0fab4' AND aktif=true;
SELECT count(*) AS adnan_ziyaret FROM saha_ziyaret WHERE rep_id='bd1787e9-2eb8-415b-9423-af3766f0fab4';
