INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('653b64f1-f5e2-5c60-a749-cd40a13cc09f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ENAS LOJİSTİK' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'2e6bcf17-ad52-502d-b565-c46b04528d64'::uuid),'bd1787e9-2eb8-415b-9423-af3766f0fab4','Adnan Karakaya','TICARI','TAMAMLANDI','2026-04-20',NULL,'GEÇEN HAFTA FİRMA SAHİBİ HÜSEYİN BEYİ ZİYARET ETTİĞİMDE 10 ADET 315 80R22.5 ÖN LASTİK ALMAYI DÜŞÜNDÜĞÜNÜ SÖYLEMİŞTİ . KİMYASAL TAŞIMACILIK SEKTÖRÜNDE HİZMET ETTİĞİNDEN İZMİR BRİSA BAYİSİ ÇAVUŞOĞLU İLE SEKTÖRDEN TANIŞIKLIKLARI VAR , 80 ADET CİVARİ DAYTON ALIMI YAPILMIŞ. GEÇMİŞTE YENİ VE KAPLAMA ÜRÜN SATIŞIMIZ OLMUŞTU . YAKLAŞIK 60 PLAKALI BİR FİLODUR . ÖDEMESİ DÜZGÜN VE MANEVİ HASSASİYETİ OLAN BİR KİŞİDİR . İSHAKOĞLU FİRMASI İLEDE TİCARETLERİ OLMUŞ. BU ZİYARETİMDE SAHA AMİRİ YAHYA İLE SOHBETİMİZ OLDU . KUMHO YU ANLATTIM BİNEK OTOMOBİLİNDE KULLANDIĞI İÇİN MARKAYA AŞİNALIĞI VAR. GARAJLARINDA 40 CİVARİ ÇIKMA LASTİKLERİ VAR HAFTAYA CUMARTESİ YAHYA İLE BİRLİKTE HURDA ANALİZİ YAPMAYA KARAR VERDİK. KUMHO İÇİN FİYAT TEKLİFİ VERMİŞTİM ....AMACIM BU FİLODA KUMHO İLE İLERLEMEK','{}'::jsonb,'EXCEL_MIGRASYON','bd1787e9-2eb8-415b-9423-af3766f0fab4') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bf9f5cdf-384b-5b85-8365-bc0558672f1c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KHN  TAŞIMACILIK' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'bfd0eafd-2098-5922-bf1c-99c1017c9e24'::uuid),'bd1787e9-2eb8-415b-9423-af3766f0fab4','Adnan Karakaya','TICARI','TAMAMLANDI','2026-04-20',NULL,'KHN LOJİSTİK FİRMASIDA KİMYA TAŞIMA SEKTÖRÜNDE HİZMET VEREN AZERBAYCAN ORTAKLI 16 ÇEKER 35 DORSESİ OLAN ÖDEMESİ DÜZGÜN BİR FİLODUR. FİRMANIN ESKİ GARAJI KÖSEKÖYDEYKEN YENİ VE KAPALAMADA SERVİS AVANTAJIMIZI KULLANARAK ÇALIŞIYORDUK... GARAJ DİLOVASI GEBKİM KİMYACILAR BÖLGESİNE TAŞININCA MESAFEDEN DOLAYI İSHAKOĞLUNDAN HİZMET ALMAYA BAŞLADILAR CONTİNENTAL FİYATIDA PİRELLİYE NAZARAN YÜKSEK KALDIĞI İÇİN İSHAKOĞLU İLE TİCARETLERİNE DEVAM ETTİLER. BU SÜRE ZARFINDA İRBİTABIMIZ HİÇ KOPMADI .GARAJ AMİRİ MEMİŞ BU ZİYARETİMDE İSHAKOĞLUNUN SATIŞ TEMSİLCİSİ BATUHANLA KARŞILAŞTIM.. SPOT MAL ALIP SATTIKLARINI SÖYLEDİ 385 65R22.5 GOODYAER K-MAX 19.000 TLYE HAVALE VE KREDİ KARTINA TEK ÇEKİM SATTIYORUM DEDİ ....ŞİLE BRİSA BAYİSİ ALBAYRAK LASTİKTE BRİSA BÖLGE YÖNETİCİSİ İLE BU FİLOYU ZİYARET ETMİŞ ....KISA ZAMANDA OLMASADA KUMHO İLE GERİ KAZANMAYI DÜŞÜNÜYORUM','{}'::jsonb,'EXCEL_MIGRASYON','bd1787e9-2eb8-415b-9423-af3766f0fab4') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fc2298a6-8692-5da2-ab11-da94cf7ae115','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAVUZLAR GRUP' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'52e098c9-334e-558e-8db8-0b23b7e2d9bd'::uuid),'bd1787e9-2eb8-415b-9423-af3766f0fab4','Adnan Karakaya','TICARI','TAMAMLANDI','2026-04-20',NULL,'HAFRİYAT SEKTÖRÜNDE HİZMET VEREN BÖLGENİN EN DÜZGÜN HAFRİYATÇILARINDAN OLAN VE HALİYLE HER LASTİÇİNİN SIK ZİYARET ETTİĞİ FİLODUR. KAPLAMADA TERCİHİNİ BİZDEN KULLANMAKTA YENİ LASTİK ALIMINI İSE ŞİMDİLİK ALTINLASTAN VE İSHAKOĞLUNDAN ( geçmişte) YAPMAKTA FİRMA SAHİBİ YAVUZ BEY İLE GÖRÜŞÜYORUM...HER ZAMAN STOKLU ÇALIŞIR ...GENEL SOHBETİMİZ OLDU BİR İNŞAAT FİRMASININ HAFRİYAT İŞİNİ YAPMIŞ ÖDEMESİ ALAMAMIŞ ....VERMİŞ OLDUĞUMUZ KARKASLI KAPLAMALARDAN 2 TANESİNDE ÜRETİMDEN KAYNAKLI SORUN ÇIKMIŞTI ONU SORDU .GARANTİDEN KABUL EDİLDİĞİNİ SÖYLEDİM 30 PLAKALI FİLODUR... BRİSA ÜRÜNLERİNİ YENİDEN SATTIĞIMIZ BİLGİSİNİ PAYLAŞTIM','{}'::jsonb,'EXCEL_MIGRASYON','bd1787e9-2eb8-415b-9423-af3766f0fab4') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d5e26fd5-9d46-54c8-aa9b-ce700c021c2c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MELSA AĞIR NAKLİYAT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'21d48b53-1882-5408-bfab-5c4d0b8b4834'::uuid),'bd1787e9-2eb8-415b-9423-af3766f0fab4','Adnan Karakaya','TICARI','TAMAMLANDI','2026-04-20',NULL,'HEDEF MÜŞTERİLERİM ARASINDA OLUP AĞIR NAKLİYAT SEKTÖRÜNDE HİZMET VEREN 30 PLAKALI FİLODUR . TATKO LASTİK İLE ÇALIŞMAKTALAR , KADEME YETKİLİSİ HÜSEYİN BEY İLE GÖRÜŞMEKTEYİM ... 245 70R17.5 TRAİLER GRUBUNDA LASSA VE BRİDGESTONE İLE SATIŞ YAPMAYI PLANLIYORUM . BİR KEZ FİYAT TEKLİFİ İSTEMİŞLERDİ 245 70R17.5 TRAİLE LASTİĞİ İÇİN CONTİNENTAL TEKLİFİ VERMİŞTİM GERİ DÖNÜŞ YAPMADILAR .YAKIN ZAMANDA 1..2 AY İÇİNDE GEBZE BALÇIK TARAFLARINDA ALMIŞ OLDUKLARI GARAJLARINA TAŞINACAKLAR YAKIN TAKİBE ALDIĞIM VE MENDUH BEY İLE ZİYARET EDECEĞİM FİLOLAR ARASINDADIR . BU ZİYARETİMDE GARAJDA KİMSE YOKTU TEKRARDAN ZİYARET EDECEĞİM BRİSA SATIŞ YÖNETİSİ İLE ZİYARET PLANLIYORUM','{}'::jsonb,'EXCEL_MIGRASYON','bd1787e9-2eb8-415b-9423-af3766f0fab4') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('128bbe22-4f0b-51ec-b760-b5e8ceaeb888','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İDA AĞIR NAKLİYAT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'dda4046e-6d91-55e4-b55a-a09a389f27a9'::uuid),'bd1787e9-2eb8-415b-9423-af3766f0fab4','Adnan Karakaya','TICARI','TAMAMLANDI','2026-04-20',NULL,'AĞIR NAKLİYAT SEKTÖRÜNDE 4 ÇEKER 5 DORSE ( DORSELER 6 DİNGİL ) 9 PLAKALI FİLODUR SAİLUN TRAİLER GRUBUNDA SATIŞIMIZ OLDU FAKAT LASTİK PERFORMANSINDAN OLUMLU SONUÇ ALINAMAYINCA MÜŞTERİYİ ŞİLE BRİSA BAYİSİ ALBAYRAK LASTİĞE KAPTIRDIK . MÜŞTERİ MEMNUNİYETİNİ GÖZ ÖNÜNDE BULUNDURARAK TELAFİ ETTİK BU SEBEPLE ŞİRKETİMİZE GÜVENLERİ TAMDIR TRAİLER LASTİK TÜKETİMİ ADETLİ FİLODUR ....GERİ KAZANILACAK BİR İLİŞKİMİZ VARDIR. BRİSA ÜRÜNLERİNİ TEKRARDAN SATMAYA BAŞLADIMIZ BİLGİSİNİ VERDİM DEPOSUNDA 20 ADET 245 70R17.5 BRİDGESTONE VAR HAFTALIK RUTİN ZİYARET EDİLECEK','{}'::jsonb,'EXCEL_MIGRASYON','bd1787e9-2eb8-415b-9423-af3766f0fab4') ON CONFLICT (id) DO NOTHING;
