INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('91ad4bc7-d38d-5672-b907-96bb56a0ed24','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OYAK BETON' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'dfff4018-75ee-571d-8ae4-41fbd6d65b41'::uuid),'bd1787e9-2eb8-415b-9423-af3766f0fab4','Adnan Karakaya','TICARI','TAMAMLANDI','2026-06-25',NULL,'OYAK BETONUN ÇERKEŞLİDEKİ OCAKLARINI GEÇEN HAFTA ZİYARET EDİP HENÜZ MONTAJI YAPILMAIŞ YENİ 4 ADET 26.5R25 PETLAS GÖRMÜŞTÜM. YETKİLİLİN İLETİŞİM BİLGİLERİNİ ALARAK TELEFONLA GÖRÜŞTÜKTEN SONRA MAİL ÜZERİNDE KAPLAMA TEKLİFİMİZİ İLETTİM...BU HAFTAKİ ZİYARETİMDE MONTAJLARIN HALEN YAPILMADIĞINI GÖRDÜM...KADEMEDEKİ MUSTAFA İLE SOHBETİMİZ ... 8 ADET 26.5 R 25 KAPLAMAYA LASTİK ÇIKACAĞINI SÖYLEDİ...KONUYU KEMAL İLE İSTİŞERE EDEREK HAFTA İÇİ KUTKÖYDEKİ OFİSLERİNİ ZİYARETE GİDECEĞİZ BU LOKASYONDA 4 ADET LODER 20 CİVARINDA KAMYON GÖRDÜM.','{}'::jsonb,'EXCEL_MIGRASYON','bd1787e9-2eb8-415b-9423-af3766f0fab4') ON CONFLICT (id) DO NOTHING;
